import java.util.concurrent.CompletableFuture;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;

public class CompletableFuturePipelineDemo {

    public static void main(String[] args) {
        ExecutorService executor = Executors.newFixedThreadPool(4);

        CompletableFuture.supplyAsync(() -> "user_123", executor)
            // thenApply: Transform String userId to User object
            .thenApply(userId -> fetchUserFromDatabase(userId))
            // thenCompose: Flatten an async dependency call (fetching user permissions)
            .thenCompose(user -> fetchPermissionsAsync(user.getId(), executor))
            // thenAccept: Terminal side-effect consumer
            .thenAccept(permissions -> System.out.println("Loaded permissions: " + permissions))
            .join();

        executor.shutdown();
    }

    private static User fetchUserFromDatabase(String userId) {
        return new User(userId, "Alice");
    }

    private static CompletableFuture<String> fetchPermissionsAsync(String userId, ExecutorService exec) {
        return CompletableFuture.supplyAsync(() -> "[READ, WRITE]", exec);
    }

    private static class User {
        private final String id;
        private final String name;
        public User(String id, String name) { this.id = id; this.name = name; }
        public String getId() { return id; }
    }
}
